_851" s="T31" e="T32">Takie </ts><ts n="e" id="Seg_853" s="T32" e="T33">są ((inc. )) ? </ts></ts><ts n="sc" id="Seg_854" s="T37" e="T39"><ts n="e" id="Seg_856" s="T37" e="T38">Ale to może podróba była jakaś wiesz hm </ts><ts n="e" id="Seg_858" s="T38" e="T39">taiwańska. </ts></ts><ts n="sc" id="Seg_859" s="T42" e="T47"><ts n="e" id="Seg_861" s="T42" e="T43">((inc. )) </ts><ts n="e" id="Seg_863" s="T43" e="T44">Nie, nie </ts><ts n="e" id="Seg_865" s="T44" e="T45">bo to nie jest jakiś/ hm jest jakiś tem</ts><ts n="e" id="Seg_867" s="T45" e="T46">at wiesz/ jest jak</ts><ts n="e" id="Seg_869" s="T46" e="T47">iś temat no. </ts></ts><ts n="sc" id="Seg_870" s="T48" e="T50"><ts n="e" id="Seg_872" s="T48" e="T49">Nie to jes</ts><ts n="e" id="Seg_874" s="T49" e="T50">t ((inc.)), bo to jest tak. </ts></ts><ts n="sc" id="Seg_875" s="T69" e="T72"><ts n="e" id="Seg_877" s="T69" e="T70">(Z) </ts><ts n="e" id="Seg_879" s="T70" e="T71">Zapałki zbieraś </ts><ts n="e" id="Seg_881" s="T71" e="T72">też? </ts></ts><ts n="sc" id="Seg_882" s="T74" e="T76"><ts n="e" id="Seg_884" s="T74" e="T75">Ty zbieraś zapał</ts><ts n="e" id="Seg_886" s="T75" e="T76">ki? </ts></ts><ts n="sc" id="Seg_887" s="T80" e="T81"><ts n="e" id="Seg_889" s="T80" e="T81">Ale co, ale… </ts></ts><ts n="sc" id="Seg_890" s="T90" e="T93"><ts n="e" id="Seg_892" s="T90" e="T91">Że p</ts><ts n="e" id="Seg_894" s="T91" e="T92">udełko mu się nie </ts><ts n="e" id="Seg_896" s="T92" e="T93">podoba. </ts></ts><ts n="sc" id="Seg_897" s="T96" e="T100"><ts n="e" id="Seg_899" s="T96" e="T97">A co jest takiego w zapałkach </ts><ts n="e" id="Seg_901" s="T97" e="T98">faj</ts><ts n="e" id="Seg_903" s="T98" e="T99">nego </ts><ts n="e" id="Seg_905" s="T99" e="T100">Paweł? </ts></ts><ts n="sc" id="Seg_906" s="T109" e="T111"><ts n="e" id="Seg_908" s="T109" e="T110">Hm˙ </ts><ts n="e" id="Seg_910" s="T110" e="T111">OK˙ </ts></ts><ts n="sc" id="Seg_911" s="T114" e="T124"><ts n="e" id="Seg_913" s="T114" e="T115">Dla ma</ts><ts n="e" id="Seg_915" s="T115" e="T116">lutkich dzieci</ts><ts n="e" id="Seg_917" s="T116" e="T117">aczkuch, tak? </ts><ts n="e" id="Seg_919" s="T117" e="T118">Sobie podpaliś domeczek, wiesz że </ts><ts n="e" id="Seg_921" s="T118" e="T119">((0,5s)) </ts><ts n="e" id="Seg_923" s="T119" e="T120">taki dwulatek hm </ts><ts n="e" id="Seg_925" s="T120" e="T121">(twiela) ((inc. )) sobie domeczek swój ma… </ts><ts n="e" id="Seg_927" s="T121" e="T122">i hm </ts><ts n="e" id="Seg_929" s="T122" e="T123">dla lalecze</ts><ts n="e" id="Seg_931" s="T123" e="T124">k, tak? </ts></ts><ts n="sc" id="Seg_932" s="T125" e="T128"><ts n="e" id="Seg_934" s="T125" e="T126">Sup</ts><ts n="e" id="Seg_936" s="T126" e="T127">er, dobrze. </ts><ts n="e" id="Seg_938" s="T127" e="T128">A dziewczyny wy coś zbieracie? </ts></ts><ts n="sc" id="Seg_939" s="T130" e="T131"><ts n="e" id="Seg_941" s="T130" e="T131">Słusz… </ts></ts><ts n="sc" id="Seg_942" s="T132" e="T136"><ts n="e" id="Seg_944" s="T132" e="T133">I jak to? </ts><ts n="e" id="Seg_946" s="T133" e="T134">No al… </ts><ts n="e" id="Seg_948" s="T134" e="T136">To/ to wy się nie wiedzałeś z kim… </ts></ts><ts n="sc" id="Seg_949" s="T137" e="T138"><ts n="e" id="Seg_951" s="T137" e="T138">z… </ts></ts><ts n="sc" id="Seg_952" s="T141" e="T142"><ts n="e" id="Seg_954" s="T141" e="T142">Hm˙ </ts></ts><ts n="sc" id="Seg_955" s="T157" e="T159"><ts n="e" id="Seg_957" s="T157" e="T158">To jest bardzo </ts><ts n="e" id="Seg_959" s="T158" e="T159">męskie i/ ((jąkanie)) i… </ts></ts><ts n="sc" id="Seg_960" s="T171" e="T174"><ts n="e" id="Seg_962" s="T171" e="T172">A co się/ </ts><ts n="e" id="Seg_964" s="T172" e="T174">a co ty spiś jak… </ts></ts><ts n="sc" id="Seg_965" s="T177" e="T180"><ts n="e" id="Seg_967" s="T177" e="T178">Przepraszam bardzo, </ts><ts n="e" id="Seg_969" s="T178" e="T179">co ty śpisz </ts><ts n="e" id="Seg_971" s="T179" e="T180">w jakimś jeziorze? </ts></ts><ts n="sc" id="Seg_972" s="T181" e="T183"><ts n="e" id="Seg_974" s="T181" e="T182">W jakimś jeziorze śpisz że to wszys</ts><ts n="e" id="Seg_976" s="T182" e="T183">tko się zmieści? </ts></ts><ts n="sc" id="Seg_977" s="T185" e="T193"><ts n="e" id="Seg_979" s="T185" e="T186">((0,2s)) Ja sobie uczer… </ts><ts n="e" id="Seg_981" s="T186" e="T187">I to sobie to wieczorem puszczasz. </ts><ts n="e" id="Seg_983" s="T187" e="T188">Wcho</ts><ts n="e" id="Seg_985" s="T188" e="T189">dzisz tam </ts><ts n="e" id="Seg_987" s="T189" e="T190">i one sobie pływaj</ts><ts n="e" id="Seg_989" s="T190" e="T191">om/ </ts><ts n="e" id="Seg_991" s="T191" e="T193">ah/ pływają sobie. </ts></ts><ts n="sc" id="Seg_992" s="T197" e="T201"><ts n="e" id="Seg_994" s="T197" e="T198">Zaprosz na</ts><ts n="e" id="Seg_996" s="T198" e="T199">s do swojego świata. </ts><ts n="e" id="Seg_998" s="T199" e="T200">((0,1s)) </ts><ts n="e" id="Seg_1000" s="T200" e="T201">(kie) ((inc. )) </ts></ts></segmentation><annotation name="en" tierref="TIE12"><ta id="Seg_1001" s="T0" e="T1">Listen, I wanted to ask you guys something about Wojtek. </ta><ta id="Seg_1002" s="T1" e="T2">Because I found out, listen, that Wojtek collects hm Kinder surprises. </ta><ta id="Seg_1003" s="T2" e="T3">Is that true? </ta><ta id="Seg_1004" s="T5" e="T7">No wait an interesting case just . </ta><ta id="Seg_1005" s="T9" e="T12">Well look you have already gathered applause Wierzuk . </ta><ta id="Seg_1006" s="T22" e="T23">Eaten? </ta><ta id="Seg_1007" s="T31" e="T33">These are ? </ta><ta id="Seg_1008" s="T37" e="T39">But it may have been a fake of some kind you know hm taiwanese . </ta><ta id="Seg_1009" s="T42" e="T47">No , no because it's not some / hm there's some topic you know / there's some topic no .</ta><ta id="Seg_1010" s="T48" e="T50">It is not , because it is so . </ta><ta id="Seg_1011" s="T69" e="T72">Do you collect from the Matchbox too? </ta><ta id="Seg_1012" s="T74" e="T76">Do you collect matches ? </ta><ta id="Seg_1013" s="T80" e="T81">But what , but ...</ta><ta id="Seg_1014" s="T90" e="T93">That he doesn't like the box . </ta><ta id="Seg_1015" s="T96" e="T100">And what is so cool about matches Paul ? </ta><ta id="Seg_1016" s="T109" e="T110">Hm ˙ </ta><ta id="Seg_1017" s="T110" e="T111">OK ˙</ta><ta id="Seg_1018" s="T114" e="T117">For little kids, right? </ta><ta id="Seg_1019" s="T117" e="T121">You know that two-year-olds, you know, they have their own little house ... </ta><ta id="Seg_1020" s="T121" e="T124">and, um, for dolls, right? </ta><ta id="Seg_1021" s="T125" e="T127">Super , good . </ta><ta id="Seg_1022" s="T127" e="T128">And you girls are collecting something ? </ta><ta id="Seg_1023" s="T130" e="T131">Right ...</ta><ta id="Seg_1024" s="T132" e="T133">And how so? </ta><ta id="Seg_1025" s="T133" e="T134">No al ... </ta><ta id="Seg_1026" s="T134" e="T136">This / that you did not know with whom ...</ta><ta id="Seg_1027" s="T137" e="T138">z ...</ta><ta id="Seg_1028" s="T141" e="T142">Hm ˙</ta><ta id="Seg_1029" s="T157" e="T159">This is very masculine and/or ...</ta><ta id="Seg_1030" s="T171" e="T174">And what do you get / and what do you sleep like ...</ta><ta id="Seg_1031" s="T177" e="T180">Excuse me , what are you sleeping in some lake ? </ta><ta id="Seg_1032" s="T181" e="T183">In what lake do you sleep that all this will fit ? </ta><ta id="Seg_1033" s="T185" e="T186">I uczer ... </ta><ta id="Seg_1034" s="T186" e="T187">And you let it go in the evening . </ta><ta id="Seg_1035" s="T187" e="T193">You go in there and they swim / ah / swim themselves . </ta><ta id="Seg_1036" s="T197" e="T199">Invite us into your world . </ta><ta id="Seg_1037" s="T200" e="T201">kie</ta></annotation><annotation name="de" tierref="TIE1"><ta id="Seg_1038" s="T0" e="T1">Hört mal, ich wollte etwas zu einer Sache von Wojtek fragen. </ta><ta id="Seg_1039" s="T1" e="T2">Weil ich mitbekommen habe, hört mal, dass Wojtek ((0,5s)) ((Luft holen)) sammelt ((0,4s)) HM Kinderüberraschungseier sammelt. </ta><ta id="Seg_1040" s="T2" e="T3">Stimmt das?</ta><ta id="Seg_1041" s="T5" e="T7">Nee, warte, das ist ja eigentlich eine interessante Sache. </ta><ta id="Seg_1042" s="T7" e="T8">((0,9s)) </ta><ta id="Seg_1043" s="T9" e="T12">Schau mal, (Wierzuk) du bekommst schon Applaus. </ta><ta id="Seg_1044" s="T22" e="T23">Aufgegessene? </ta><ta id="Seg_1045" s="T31" e="T32">Solche</ta><ta id="Seg_1046" s="T32" e="T33">gibts ((unv. )) ? </ta><ta id="Seg_1047" s="T37" e="T39">Aber das war vielleicht irgendeine taiwanesische Nachmachung HM. </ta><ta id="Seg_1048" s="T42" e="T43">((unv. )) </ta><ta id="Seg_1049" s="T43" e="T47">Nein, nein,weil das nicht irgendein/ das ist irgendein Thema, weißt du, das ist irgendein Thema. </ta><ta id="Seg_1050" s="T48" e="T50">Nein, das ist ((unv.)), weil das so ist. </ta><ta id="Seg_1051" s="T70" e="T72">Streichhölzer sammelst du auch? </ta><ta id="Seg_1052" s="T74" e="T76">Sammelst du Streichhölzer? </ta><ta id="Seg_1053" s="T80" e="T81">Aber was, aber… </ta><ta id="Seg_1054" s="T90" e="T93">Dass ihm die Schachtel nicht gefällt. </ta><ta id="Seg_1055" s="T96" e="T100">Und was ist so toll an Streichhölzern Paweł? </ta><ta id="Seg_1056" s="T109" e="T110">HM˙ </ta><ta id="Seg_1057" s="T110" e="T111">OK˙ </ta><ta id="Seg_1058" s="T114" e="T117">Für kleine Kinderchen, ja? </ta><ta id="Seg_1059" s="T117" e="T118">Zündest du das Häuschen an, weißt du, dass </ta><ta id="Seg_1060" s="T118" e="T119">((0,5s)) </ta><ta id="Seg_1061" s="T119" e="T124">so ein Zweijähriger ((unv. )) hat sein kleines Häuschen und HM für Puppen, ja?</ta><ta id="Seg_1062" s="T125" e="T127">Super, gut. </ta><ta id="Seg_1063" s="T127" e="T128">Und die Mädels, sammelt ihr irgendetwas?</ta><ta id="Seg_1064" s="T130" e="T131">Richtig… </ta><ta id="Seg_1065" s="T132" e="T133">Und wie? </ta><ta id="Seg_1066" s="T134" e="T136">Aber dann wußtet ihr gar nicht mit wem… </ta><ta id="Seg_1067" s="T137" e="T138">mit… </ta><ta id="Seg_1068" s="T141" e="T142">HM˙ </ta><ta id="Seg_1069" s="T157" e="T159">Das ist sehr männlich und/ ((Stottern)) und… </ta><ta id="Seg_1070" s="T171" e="T174">Und was =/ aber wie, du schläfst wie… </ta><ta id="Seg_1071" s="T177" e="T180">Entschuldige mal, schläfst du in irgendeinem See? </ta><ta id="Seg_1072" s="T181" e="T183">Schläfst du in irgendeinem See, dass das alles reinpaßt? </ta><ta id="Seg_1073" s="T185" e="T186">((0,2s)) Ich = mir… </ta><ta id="Seg_1074" s="T186" e="T187">Und du lässt Dir abends. </ta><ta id="Seg_1075" s="T187" e="T193">Gehst da rein und die schwimmen/ ah/ schwimmen dann vor sich hin. </ta><ta id="Seg_1076" s="T197" e="T199">Lad uns in Deine Welt ein. </ta><ta id="Seg_1077" s="T199" e="T200">((0,1s)) </ta><ta id="Seg_1078" s="T200" e="T201">((unv. )) </ta></annotation></segmented-tier><segmented-tier id="TIE2" speaker="SPK1" category="v" type="t" display-name="WojM [v]"><timeline-fork start="T5" end="T6"><tli id="T5.TIE2.1"/>
