T:w" id="Seg_3476" s="T174.TIE6.2" e="T175">balkonie</ts><nts n="HIAT:ip" id="Seg_3477">.</nts><nts n="HIAT:ip" id="Seg_3478"><![CDATA[ ]]></nts></ts></ts></segmentation><segmentation name="SpeakerContribution_Event" tierref="TIE6"><ts n="sc" id="Seg_3479" s="T14" e="T16"><ts n="e" id="Seg_3481" s="T14" e="T16">((śmiech)) </ts></ts><ts n="sc" id="Seg_3482" s="T44" e="T45"><ts n="e" id="Seg_3484" s="T44" e="T45">((śmiech)) </ts></ts><ts n="sc" id="Seg_3485" s="T52" e="T56"><ts n="e" id="Seg_3487" s="T52" e="T56">((śmiech)) </ts></ts><ts n="sc" id="Seg_3488" s="T59" e="T60"><ts n="e" id="Seg_3490" s="T59" e="T60">ɔ́ ɔ̀˙ </ts></ts><ts n="sc" id="Seg_3491" s="T78" e="T82"><ts n="e" id="Seg_3493" s="T78" e="T79">Jezus Maria! </ts><ts n="e" id="Seg_3495" s="T79" e="T80">J</ts><ts n="e" id="Seg_3497" s="T80" e="T81">uż nic nie mam </ts><ts n="e" id="Seg_3499" s="T81" e="T82">na to. </ts></ts><ts n="sc" id="Seg_3500" s="T85" e="T87"><ts n="e" id="Seg_3502" s="T85" e="T87">((śmiech)) </ts></ts><ts n="sc" id="Seg_3503" s="T129" e="T130"><ts n="e" id="Seg_3505" s="T129" e="T130">No ale, ale w ogóle się n… </ts></ts><ts n="sc" id="Seg_3506" s="T134" e="T147"><ts n="e" id="Seg_3508" s="T134" e="T135">A w ogóle nie wiedziała Pause ((0,3s)) ((jąkanie)) </ts><ts n="e" id="Seg_3510" s="T135" e="T137">w/ w/ my/ </ts><ts n="e" id="Seg_3512" s="T137" e="T138">że </ts><ts n="e" id="Seg_3514" s="T138" e="T139">Mecek zbiera hm/ </ts><ts n="e" id="Seg_3516" s="T139" e="T140">hm te jajka niespodzianki. </ts><ts n="e" id="Seg_3518" s="T140" e="T141">hm On dużo hm różnych rzeczy </ts><ts n="e" id="Seg_3520" s="T141" e="T142">z</ts><ts n="e" id="Seg_3522" s="T142" e="T143">biera. </ts><ts n="e" id="Seg_3524" s="T143" e="T144">Ma jakieś tam kaczuszki do kąpieli prze różne. </ts><ts n="e" id="Seg_3526" s="T144" e="T145">No powiedz </ts><ts n="e" id="Seg_3528" s="T145" e="T146">((inc. )) </ts><ts n="e" id="Seg_3530" s="T146" e="T147">prawda! </ts></ts><ts n="sc" id="Seg_3531" s="T149" e="T152"><ts n="e" id="Seg_3533" s="T149" e="T150">Ja </ts><ts n="e" id="Seg_3535" s="T150" e="T151">przepraszam. </ts><ts n="e" id="Seg_3537" s="T151" e="T152">((inc.)) coś. </ts></ts><ts n="sc" id="Seg_3538" s="T156" e="T161"><ts n="e" id="Seg_3540" s="T156" e="T157">A to teraz chce </ts><ts n="e" id="Seg_3542" s="T157" e="T158">się popisać. </ts><ts n="e" id="Seg_3544" s="T158" e="T159">Kaczki do kompiel</ts><ts n="e" id="Seg_3546" s="T159" e="T160">i… </ts><ts n="e" id="Seg_3548" s="T160" e="T161">Chodź, nie kłam! </ts></ts><ts n="sc" id="Seg_3549" s="T166" e="T167"><ts n="e" id="Seg_3551" s="T166" e="T167">I (Odzy) korzysta z tego. </ts></ts><ts n="sc" id="Seg_3552" s="T168" e="T169"><ts n="e" id="Seg_3554" s="T168" e="T169">Się z tym kąpie. </ts></ts><ts n="sc" id="Seg_3555" s="T172" e="T175"><ts n="e" id="Seg_3557" s="T172" e="T174">Mamy dmuchany bas</ts><ts n="e" id="Seg_3559" s="T174" e="T175">en na balkonie. </ts></ts></segmentation><annotation name="en" tierref="TIE15"><ta id="Seg_3560" s="T14" e="T16"></ta><ta id="Seg_3561" s="T59" e="T60">ɔ́ ɔ̀ ˙</ta><ta id="Seg_3562" s="T78" e="T79">Jesus Maria ! </ta><ta id="Seg_3563" s="T79" e="T82">I have nothing left for it .</ta><ta id="Seg_3564" s="T129" e="T130">Well, but , but at all n ...</ta><ta id="Seg_3565" s="T134" e="T140">And she didn't know at all Pause w / w / us / that Mecek collects hm / hm those surprise eggs . </ta><ta id="Seg_3566" s="T140" e="T143">hm He collects a lot of hm different things . </ta><ta id="Seg_3567" s="T143" e="T144">He's got some bath ducks over there . </ta><ta id="Seg_3568" s="T144" e="T147">Well tell the truth ! </ta><ta id="Seg_3569" s="T149" e="T152">I'm sorry . something . </ta><ta id="Seg_3570" s="T156" e="T158">And it now wants to show off . </ta><ta id="Seg_3571" s="T158" e="T160">Ducks for a bath ... </ta><ta id="Seg_3572" s="T160" e="T161">Come on , don't lie ! </ta><ta id="Seg_3573" s="T166" e="T167">And Odzy is taking advantage of this . </ta><ta id="Seg_3574" s="T168" e="T169">I am bathing with it . </ta><ta id="Seg_3575" s="T172" e="T175">We have an inflatable pool on the balcony . </ta></annotation><annotation name="de" tierref="TIE7"><ta id="Seg_3576" s="T14" e="T16">((Lachen)) </ta><ta id="Seg_3577" s="T44" e="T45">((Lachen)) </ta><ta id="Seg_3578" s="T52" e="T56">((Lachen)) </ta><ta id="Seg_3579" s="T59" e="T60">oh oh˙ </ta><ta id="Seg_3580" s="T78" e="T79">Oh Gott! </ta><ta id="Seg_3581" s="T79" e="T82">Da fällt mir nichts mehr zu ein. </ta><ta id="Seg_3582" s="T85" e="T87">((Lachen)) </ta><ta id="Seg_3583" s="T129" e="T130">Ja aber, ich… mich überhaupt (nicht) </ta><ta id="Seg_3584" s="T134" e="T135">A ich habe überhaupt nicht gewußt ((0,2s)) ((Stottern)) </ta><ta id="Seg_3585" s="T135" e="T137">in/ in/ wir/ </ta><ta id="Seg_3586" s="T137" e="T140">dass Mecek diese Überraschungseier sammelt. </ta><ta id="Seg_3587" s="T140" e="T143">HM, er sammelt viele verschiedene Dinge. </ta><ta id="Seg_3588" s="T143" e="T144">Er hat da irgendwelche verschiedenen Quietscheenten. </ta><ta id="Seg_3589" s="T144" e="T147">Komm erzähl ((unv. )) die Wahrheit! </ta><ta id="Seg_3590" s="T149" e="T151">Entschuldigung. </ta><ta id="Seg_3591" s="T156" e="T158">Ach, da möchte er sich jetzt profilieren. </ta><ta id="Seg_3592" s="T158" e="T160">Quietscheentchen… </ta><ta id="Seg_3593" s="T160" e="T161">Na komm, lüg nicht!</ta><ta id="Seg_3594" s="T166" e="T167">Und (Odzy) benutzt sie. </ta><ta id="Seg_3595" s="T168" e="T169">Er badet damit. </ta><ta id="Seg_3596" s="T172" e="T175">Wir haben einen aufblasbaren Pool auf dem Balkon. </ta></annotation><annotation name="k" tierref="TIE10"><ta id="Seg_3597" s="T135" e="T137">stotternd</ta></annotation></segmented-tier><segmented-tier id="TIE8" speaker="SPK3" category="v" type="t" display-name="MagR [v]"><timeline-fork start="T56" end="T58"><tli id="T56.TIE8.1"/>
